    <script>
        // Icons
        lucide.createIcons();

        // Mobile Menu
        const mobileMenuBtn = document.getElementById('mobile-menu-btn');
        const mobileMenu = document.getElementById('mobile-menu');
        if(mobileMenuBtn && mobileMenu) {{
            mobileMenuBtn.addEventListener('click', () => {{
                mobileMenu.classList.toggle('hidden');
            }});
        }}

        // Accordions
        document.querySelectorAll('.accordion-btn').forEach(button => {{
            button.addEventListener('click', () => {{
                const content = button.nextElementSibling;
                const icon = button.querySelector('.accordion-icon');
                const isExpanded = content.classList.contains('active');

                // Close all in this group (optional, can be modified)
                const parent = button.closest('.accordion-group');
                if(parent) {{
                    parent.querySelectorAll('.accordion-content').forEach(c => c.classList.remove('active'));
                    parent.querySelectorAll('.accordion-icon').forEach(i => i.classList.remove('active'));
                }}

                if (!isExpanded) {{
                    content.classList.add('active');
                    icon.classList.add('active');
                }}
            }});
        }});

        // Tabs
        document.querySelectorAll('.tab-btn').forEach(button => {{
            button.addEventListener('click', () => {{
                const targetId = button.getAttribute('data-target');
                const group = button.getAttribute('data-group');

                // Reset buttons
                document.querySelectorAll(`.tab-btn[data-group="${{group}}"]`).forEach(b => {{
                    b.classList.remove('bg-brand-lime', 'text-brand-black', 'border-brand-black');
                    b.classList.add('bg-white', 'text-gray-500', 'border-transparent');
                }});

                // Activate button
                button.classList.add('bg-brand-lime', 'text-brand-black', 'border-brand-black');
                button.classList.remove('bg-white', 'text-gray-500', 'border-transparent');

                // Reset content
                document.querySelectorAll(`.tab-content[data-group="${{group}}"]`).forEach(c => {{
                    c.classList.remove('active');
                }});

                // Activate content
                document.getElementById(targetId).classList.add('active');
            }});
        }});

        // Carousels
        document.querySelectorAll('.carousel-container').forEach(container => {{
            const track = container.querySelector('.carousel-track');
            const prevBtn = container.querySelector('.carousel-prev');
            const nextBtn = container.querySelector('.carousel-next');
            const cards = container.querySelectorAll('.carousel-card');

            if(!track || !cards.length || !prevBtn || !nextBtn) return;

            let currentIndex = 0;
            const updateCarousel = () => {{
                const cardWidth = cards[0].offsetWidth;
                const gap = parseInt(window.getComputedStyle(track).gap) || 0;
                track.style.transform = `translateX(-${{currentIndex * (cardWidth + gap)}}px)`;
            }};

            nextBtn.addEventListener('click', () => {{
                if (currentIndex < cards.length - 1) {{
                    currentIndex++;
                    updateCarousel();
                }}
            }});

            prevBtn.addEventListener('click', () => {{
                if (currentIndex > 0) {{
                    currentIndex--;
                    updateCarousel();
                }}
            }});

            window.addEventListener('resize', updateCarousel);
        }});
    </script>
